def seed(apps, schema_editor):
    Option = apps.get_model("profiles", "VocabularyOption")

    def put(vocabulary, options, parent=None):
        for order, (code, label) in enumerate(options):
            Option.objects.update_or_create(
                vocabulary=vocabulary,
                code=code,
                defaults={
                    "label_en": label,
                    "sort_order": order * 10,
                    "is_active": True,
                    **({"parent": parent} if parent is not None else {}),
                },
            )

    for religion, options in DENOMINATIONS.items():
        put("denomination", options, Option.objects.get(vocabulary="religion", code=religion))
    put("caste", CASTES)
    for caste, options in SUB_CASTES.items():
        parent = Option.objects.get(vocabulary="caste", code=caste) if caste else None
        put("sub_caste", options, parent)
    put("community", COMMUNITIES)


